// Original English retellings of Genesis, with passage references for family reading.
// Scene artwork is a symbolic collection illustration, not a picture of every event.
export const genesisCollections = [
  { id: 'beginnings', title: 'The Beginnings', subtitle: 'Creation, Noah, and Babel', image: 'creation', color: 'garden' },
  { id: 'abraham', title: 'Abraham & Sarah', subtitle: 'Journeys and promises', image: 'abraham', color: 'sunrise' },
  { id: 'isaac', title: 'Isaac & Two Brothers', subtitle: 'Choices and family', image: 'abraham', color: 'garden' },
  { id: 'jacob', title: 'Jacob & His Family', subtitle: 'Growing and making peace', image: 'abraham', color: 'ocean' },
  { id: 'joseph', title: 'Joseph & His Brothers', subtitle: 'Hope and forgiveness', image: 'joseph', color: 'sunrise' },
];

// Each question is authored as [prompt, answer, distractor, distractor, explanation].
// Rotate the correct answer so children need to read rather than memorize a position.
function episode(collection, data) {
  const group = genesisCollections.find(item => item.id === collection);
  return {
    ...data, contentRevision: 2, bookId: 'genesis', collection,
    image: `assets/kids-bible/genesis/${data.art || group.image}.svg`,
    color: group.color, coverPosition: '50%', minutes: data.scenes.length === 4 ? 5 : 4,
    intro: data.subtitle,
    scenes: data.scenes.map(([title, text]) => ({ title, text, position: '50%' })),
    questions: data.questions.map(([question, answer, other, last, explanation], index) => {
      const choices = [other, last];
      const correct = (Array.from(data.id).reduce((sum, letter) => sum + letter.charCodeAt(0), 0) + index) % 3;
      choices.splice(correct, 0, answer);
      return { question, choices: choices.map(text => ['✦', text]), correct, explanation };
    }),
  };
}

